{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')
THERAPY_CATALOG = ROOT / 'therapy_catalog.json'
BAG_SUPPLY_COST = ROOT / 'bag_supply_cost.csv'
DELIVERY_PAYMENT = ROOT / 'delivery_payment.csv'
PATIENT_OVERRIDES = ROOT / 'patient_overrides.csv'
ANALYSIS_OUT = ROOT / 'infusion_batch_analysis.json'
SUMMARY_OUT = ROOT / 'infusion_batch_summary.md'


def norm_label(value):
    return ' '.join(str(value).strip().casefold().replace('-', ' ').split())


def to_float(value, field):
    try:
        return float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f'Could not parse numeric field {field!r}: {value!r}') from exc


def to_int(value, field):
    try:
        return int(float(value))
    except (TypeError, ValueError) as exc:
        raise ValueError(f'Could not parse integer field {field!r}: {value!r}') from exc


def money(value):
    # Round to two decimals for all currency outputs.
    return round(float(value) + 1e-9, 2)


def load_catalog(path):
    with path.open('r', encoding='utf-8') as f:
        catalog = json.load(f)

    therapies = []
    for service_line in catalog.get('service_lines', []):
        service_line_name = service_line.get('service_line')
        for therapy in service_line.get('therapies', []):
            entry = dict(therapy)
            entry['service_line'] = service_line_name
            if entry.get('include_in_review') is True:
                therapies.append(entry)
    return therapies


def load_bag_costs(path):
    costs = {}
    with path.open('r', encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            bag_size = to_int(row.get('bag_size_ml'), 'bag_size_ml')
            costs[bag_size] = to_float(row.get('bag_supply_cost_usd'), 'bag_supply_cost_usd')
    return costs


def load_delivery_payments(path, in_scope_therapies):
    label_to_code = {}
    for therapy in in_scope_therapies:
        labels = [therapy.get('therapy_name', '')] + list(therapy.get('aliases') or [])
        for label in labels:
            label_to_code[norm_label(label)] = therapy['therapy_code']

    payments = {}
    with path.open('r', encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            label = row.get('therapy_label', '')
            code = label_to_code.get(norm_label(label))
            if not code:
                continue
            payments[code] = to_float(
                row.get('payment_per_delivery_per_patient_usd'),
                'payment_per_delivery_per_patient_usd',
            )
    return payments


def load_patient_overrides(path, in_scope_codes):
    chosen = {}
    with path.open('r', encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        headers = reader.fieldnames or []
        if 'active_patients' in headers:
            patient_field = 'active_patients'
        elif 'patient_count' in headers:
            patient_field = 'patient_count'
        else:
            raise ValueError('patient_overrides.csv must contain active_patients or patient_count')

        for row in reader:
            code = row.get('therapy_code')
            if code not in in_scope_codes:
                continue
            if str(row.get('status', '')).strip().casefold() != 'approved':
                continue
            revision = to_int(row.get('revision'), 'revision')
            active_patients = to_int(row.get(patient_field), patient_field)
            existing = chosen.get(code)
            if existing is None or revision > existing['revision']:
                chosen[code] = {
                    'therapy_code': code,
                    'revision': revision,
                    'status': row.get('status'),
                    'active_patients': active_patients,
                    'patient_count_field': patient_field,
                }
    return chosen


def model_values(therapy, active_patients, bag_supply_cost, payment, days_per_delivery, deliveries_per_year):
    drug_cost_per_1000 = to_float(therapy.get('drug_cost_per_1000_mg_usd'), 'drug_cost_per_1000_mg_usd')
    dose_per_day = to_float(therapy.get('dose_mg_per_day'), 'dose_mg_per_day')
    annual_drug_cost = drug_cost_per_1000 * active_patients * dose_per_day * days_per_delivery * deliveries_per_year / 1000
    annual_supply_cost = bag_supply_cost * active_patients * deliveries_per_year
    annual_revenue = payment * active_patients * deliveries_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost
    return {
        'days_per_delivery': days_per_delivery,
        'deliveries_per_year': deliveries_per_year,
        'annual_drug_cost_usd': money(annual_drug_cost),
        'annual_supply_cost_usd': money(annual_supply_cost),
        'annual_revenue_usd': money(annual_revenue),
        'annual_margin_usd': money(annual_margin),
    }


def main():
    in_scope_therapies = load_catalog(THERAPY_CATALOG)
    in_scope_codes = {therapy['therapy_code'] for therapy in in_scope_therapies}
    bag_costs = load_bag_costs(BAG_SUPPLY_COST)
    payments = load_delivery_payments(DELIVERY_PAYMENT, in_scope_therapies)
    patient_overrides = load_patient_overrides(PATIENT_OVERRIDES, in_scope_codes)

    therapy_rows = []
    for therapy in in_scope_therapies:
        code = therapy['therapy_code']
        bag_size = to_int(therapy.get('bag_size_ml'), 'bag_size_ml')
        missing = []
        if bag_size not in bag_costs:
            missing.append(f'bag supply cost for {bag_size} ml')
        if code not in payments:
            missing.append('delivery payment')
        if code not in patient_overrides:
            missing.append('approved patient override')
        if missing:
            raise ValueError(f'{code} missing required data: {", ".join(missing)}')

        bag_supply_cost = bag_costs[bag_size]
        payment = payments[code]
        override = patient_overrides[code]
        active_patients = override['active_patients']

        seven = model_values(therapy, active_patients, bag_supply_cost, payment, 7, 52)
        fourteen = model_values(therapy, active_patients, bag_supply_cost, payment, 14, 26)
        difference = money(fourteen['annual_margin_usd'] - seven['annual_margin_usd'])

        therapy_rows.append({
            'therapy_code': code,
            'therapy_name': therapy.get('therapy_name'),
            'service_line': therapy.get('service_line'),
            'aliases': therapy.get('aliases') or [],
            'include_in_review': therapy.get('include_in_review'),
            'active_patients': active_patients,
            'patient_override_revision': override['revision'],
            'bag_size_ml': bag_size,
            'bag_supply_cost_usd': money(bag_supply_cost),
            'payment_per_delivery_per_patient_usd': money(payment),
            'drug_cost_per_1000_mg_usd': money(to_float(therapy.get('drug_cost_per_1000_mg_usd'), 'drug_cost_per_1000_mg_usd')),
            'dose_mg_per_day': to_float(therapy.get('dose_mg_per_day'), 'dose_mg_per_day'),
            'annual_drug_cost_7_day_usd': seven['annual_drug_cost_usd'],
            'annual_supply_cost_7_day_usd': seven['annual_supply_cost_usd'],
            'annual_revenue_7_day_usd': seven['annual_revenue_usd'],
            'annual_margin_7_day_usd': seven['annual_margin_usd'],
            'annual_drug_cost_14_day_usd': fourteen['annual_drug_cost_usd'],
            'annual_supply_cost_14_day_usd': fourteen['annual_supply_cost_usd'],
            'annual_revenue_14_day_usd': fourteen['annual_revenue_usd'],
            'annual_margin_14_day_usd': fourteen['annual_margin_usd'],
            'annual_margin_difference_14_minus_7_usd': difference,
            'model_7_day': seven,
            'model_14_day': fourteen,
        })

    therapy_rows.sort(key=lambda row: row['therapy_code'])

    total_7 = money(sum(row['annual_margin_7_day_usd'] for row in therapy_rows))
    total_14 = money(sum(row['annual_margin_14_day_usd'] for row in therapy_rows))
    total_difference = money(total_14 - total_7)
    absolute_difference = money(abs(total_difference))
    decision = 'move_to_14_day' if absolute_difference < 15000 else 'keep_7_day'
    justification = (
        f'Absolute total annual margin difference is ${absolute_difference:,.2f}, '
        f"which is {'below' if absolute_difference < 15000 else 'at or above'} the $15,000 threshold; "
        f'therefore the recommendation is {decision}.'
    )

    analysis = {
        'assumptions': {
            'currency': 'USD',
            'review_filter': 'include_in_review == true',
            'delivery_payment_matching': 'therapy_label matched case-insensitively to therapy_name or aliases after hyphen/whitespace normalization; unmatched rows ignored',
            'patient_override_filter': 'status == approved; highest revision retained per in-scope therapy_code',
            'bag_supply_join': 'bag_size_ml',
            'annual_drug_cost_formula': 'drug_cost_per_1000_mg_usd * active_patients * dose_mg_per_day * days_per_delivery * deliveries_per_year / 1000',
            'annual_supply_cost_formula': 'bag_supply_cost_usd * active_patients * deliveries_per_year',
            'annual_revenue_formula': 'payment_per_delivery_per_patient_usd * active_patients * deliveries_per_year',
            'models': {
                '7_day': {'days_per_delivery': 7, 'deliveries_per_year': 52},
                '14_day': {'days_per_delivery': 14, 'deliveries_per_year': 26},
            },
            'decision_rule': 'if abs(total_difference) < 15000 then move_to_14_day else keep_7_day',
            'rounding': 'currency values rounded to 2 decimal places',
        },
        'therapies': therapy_rows,
        'totals': {
            'total_annual_margin_7_day_usd': total_7,
            'total_annual_margin_14_day_usd': total_14,
            'total_annual_margin_difference_14_minus_7_usd': total_difference,
            'absolute_total_margin_difference_usd': absolute_difference,
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    with ANALYSIS_OUT.open('w', encoding='utf-8') as f:
        json.dump(analysis, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# Infusion Batch Analysis Summary',
        f'Total 7-day margin: ${total_7:,.2f}',
        f'Total 14-day margin: ${total_14:,.2f}',
        f'Absolute difference: ${absolute_difference:,.2f}',
        f'Final decision: {decision}',
        f'Justification: {justification}',
    ]
    SUMMARY_OUT.write_text('\n'.join(summary_lines) + '\n', encoding='utf-8')


if __name__ == '__main__':
    main()
